import React, { useState } from 'react';
import { motion} from 'framer-motion';
import { Shield, Fingerprint, Cpu, ArrowRight, Activity, Zap } from 'lucide-react';

const SignIn = ({ onLogin }) => {
  const [loading, setLoading] = useState(false);

  const handleAuth = (e) => {
    e.preventDefault();
    setLoading(true);
    setTimeout(() => onLogin(), 2000);
  };

  return (
    <div className="h-screen w-full bg-[#0a0a0a] flex items-center justify-center font-sans overflow-hidden">

      {/* --- JAW-DROPPING BACKGROUND ANIMATION --- */}
      {/* This creates a soft, moving "energy field" behind the glass */}
      <div className="absolute inset-0 overflow-hidden">
        <motion.div 
          animate={{ 
            scale: [1, 1.2, 1],
            rotate: [0, 90, 0],
            x: [0, 100, 0] 
          }}
          transition={{ duration: 20, repeat: Infinity, ease: "linear" }}
          className="absolute -top-[20%] -left-[10%] w-[70%] h-[70%] bg-[#47510B]/30 rounded-full blur-[120px]"
        />
        <motion.div 
          animate={{ 
            scale: [1, 1.5, 1],
            rotate: [0, -120, 0],
            x: [0, -50, 0] 
          }}
          transition={{ duration: 15, repeat: Infinity, ease: "linear" }}
          className="absolute -bottom-[10%] -right-[10%] w-[60%] h-[60%] bg-[#FF5B03]/10 rounded-full blur-[100px]"
        />
      </div>

      {/* --- THE SIGN-IN TERMINAL --- */}
      <motion.div 
        initial={{ opacity: 0, y: 40, backdropFilter: "blur(0px)" }}
        animate={{ opacity: 1, y: 0, backdropFilter: "blur(40px)" }}
        transition={{ duration: 1, ease: [0.22, 1, 0.36, 1] }}
        className="relative w-full max-w-[480px] bg-white/[0.03] border border-white/10 rounded-[40px] p-12 shadow-[0_32px_64px_rgba(0,0,0,0.5)] overflow-hidden"
      >
        {/* Top-Edge "Scanner" Line */}
        <div className="absolute top-0 left-0 w-full h-[2px] bg-gradient-to-r from-transparent via-[#CAD23C] to-transparent animate-scan" />

        {/* LOGO AREA */}
        <div className="relative mb-12 flex flex-col items-center">
          <div className="relative group">
            <div className="absolute inset-0 bg-[#CAD23C] blur-2xl opacity-20 group-hover:opacity-40 transition-opacity" />
            <div className="relative w-20 h-20 bg-black/40 border border-white/20 rounded-2xl flex items-center justify-center mb-6">
              <Cpu className="text-[#CAD23C]" size={32} />
              {/* Spinning outer ring */}
              <div className="absolute inset-0 border-2 border-dashed border-[#CAD23C]/30 rounded-2xl animate-[spin_10s_linear_infinity]" />
            </div>
          </div>
          <h2 className="text-3xl font-black text-white tracking-tighter uppercase italic leading-none">
            Vanguard <span className="text-[#CAD23C]">OS</span>
          </h2>
          <div className="flex items-center gap-2 mt-2">
            <div className="w-1 h-1 bg-[#CAD23C] rounded-full animate-pulse" />
            <span className="text-[10px] font-bold text-white/30 uppercase tracking-[0.4em]">Biometric Auth Active</span>
          </div>
        </div>

        {/* FORM FIELD AREA */}
        <form onSubmit={handleAuth} className="space-y-6 relative z-10">
          <div className="group relative">
            <label className="absolute left-6 -top-2.5 bg-[#0a0a0a] px-2 text-[9px] font-black text-[#CAD23C] uppercase tracking-widest z-20">Operator ID</label>
            <input 
              required
              type="text" 
              placeholder="V-091-SYSTEM"
              className="w-full bg-white/[0.05] border border-white/10 p-5 pl-8 rounded-2xl text-white font-medium outline-none focus:border-[#CAD23C]/50 focus:ring-1 ring-[#CAD23C]/20 transition-all placeholder-white/10"
            />
          </div>

          <div className="group relative">
            <label className="absolute left-6 -top-2.5 bg-[#0a0a0a] px-2 text-[9px] font-black text-[#CAD23C] uppercase tracking-widest z-20">Security Clearance</label>
            <input 
              required
              type="password" 
              placeholder="••••••••"
              className="w-full bg-white/[0.05] border border-white/10 p-5 pl-8 rounded-2xl text-white font-medium outline-none focus:border-[#CAD23C]/50 focus:ring-1 ring-[#CAD23C]/20 transition-all placeholder-white/10"
            />
          </div>

          {/* ACTION BUTTON - JAW DROPPING EFFECT */}
          <motion.button
            whileHover={{ scale: 1.02, boxShadow: "0 0 30px rgba(202, 210, 60, 0.2)" }}
            whileTap={{ scale: 0.98 }}
            className="w-full py-5 rounded-2xl bg-[#CAD23C] text-[#47510B] font-black uppercase tracking-widest flex items-center justify-center gap-3 relative overflow-hidden group"
          >
            {loading ? (
              <Activity className="animate-spin" size={24} />
            ) : (
              <>
                <span>Initialize Core</span>
                <ArrowRight size={20} className="group-hover:translate-x-1 transition-transform" />
              </>
            )}
            {/* The Shine Effect */}
            <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
          </motion.button>
        </form>

        {/* FOOTER STATS */}
        <div className="mt-12 pt-8 border-t border-white/5 flex justify-between items-center opacity-40">
          <div className="flex gap-4">
             <Zap size={14} className="text-white" />
             <Shield size={14} className="text-white" />
          </div>
          <span className="text-[9px] font-black text-white uppercase tracking-widest">Protocol_72_B</span>
        </div>
      </motion.div>

      {/* CSS For Scanline Animation */}
      <style>{`
        @keyframes scan {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        .animate-scan {
          animation: scan 3s linear infinity;
        }
      `}</style>
    </div>
  );
};

export default SignIn;
